import {useRef} from "react";
import {Pressable,Text} from "react-native";
import {createStore,type StoreApi} from "zustand/vanilla";
import {useStore} from "zustand";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {filePickerRecipe,type FilePickerProps} from "@/components/nyc-tron/ui/components/files/FilePicker.types";

export type {FilePickerProps,NativeDocument,NativeDocumentSource} from "@/components/nyc-tron/ui/components/files/FilePicker.types";

/**
 * iOS and Android: a button that opens the OS document picker through
 * `documentSource` and hands the picked URIs to `onDocuments`. React Native
 * has no `File`, so this is a separate contract from web's `onFiles`; the
 * kit takes no picker dependency of its own.
 *
 * Without both `documentSource` and `onDocuments` it renders nothing, on
 * purpose: a button that opened nothing would be a dead control. While the
 * picker is open the button is busy, so a second tap cannot stack pickers.
 */
export function FilePicker({
  label,accept,multiple=false,disabled=false,documentSource,onDocuments,onError,accessibilityHint,testID,
  className,labelClassName,unstyled=false,
}:FilePickerProps){
  const local=useRef<StoreApi<{busy:boolean}>|null>(null);
  if(!local.current)local.current=createStore(()=>({busy:false}));
  const store=local.current;
  const busy=useStore(store,s=>s.busy);
  if(!documentSource||!onDocuments)return null;
  const blocked=disabled||busy;
  const open=async()=>{
    if(blocked)return;
    store.setState({busy:true});
    try{
      const documents=await documentSource.pick({...(accept?{accept}:{}),multiple});
      if(documents.length)onDocuments(documents);
    }catch(error){
      const failure=error instanceof Error?error:new Error(String(error));
      if(onError)onError(failure);else throw failure;
    }finally{
      store.setState({busy:false});
    }
  };
  const styled=!unstyled;
  return (
    <Pressable onPress={open} disabled={blocked} testID={testID}
      accessibilityRole="button" accessibilityLabel={label} accessibilityHint={accessibilityHint}
      accessibilityState={{disabled:blocked,busy}}
      {...{className:joinClasses(styled&&filePickerRecipe.root,blocked&&"opacity-50",className)}}>
      <Text {...{className:joinClasses(styled&&filePickerRecipe.label,labelClassName)}}>{label}</Text>
    </Pressable>
  );
}

/** A file a native picker returned: a URI, not a `File`. */
export interface NativeDocument {
  readonly uri:string;
  readonly name:string;
  readonly size?:number;
  readonly mimeType?:string;
  /** Reopens an open-in-place pick in a later launch. */
  readonly bookmark?:string;
}

/** Opens the OS document picker. `accept` uses the same syntax as the web prop. */
export interface NativeDocumentSource {
  pick(options:{accept?:string;multiple?:boolean}):Promise<readonly NativeDocument[]>;
}

/** Props for FilePicker. Drop-in for the `FilePicker` Nitro Forge's studio preview imports. */
export interface FilePickerProps {
  /** Visible text and accessible name, e.g. "Open". */
  label:string;
  /** HTML input syntax, e.g. ".docx,.nfd". */
  accept?:string;
  multiple?:boolean;
  disabled?:boolean;
  /** Web: called once per pick with at least one file; cancelling calls nothing. Without it web renders nothing. */
  onFiles?:(files:File[])=>void;
  /**
   * iOS and Android: the OS document picker, e.g.
   * `documentPickerSource(createPlatformDocuments())` from
   * `@nyc-tron/platform-services/documents`. Native renders the button only
   * when this and `onDocuments` are both set. Web ignores it.
   */
  documentSource?:NativeDocumentSource;
  /** iOS and Android: called once per pick with at least one document; cancelling calls nothing. */
  onDocuments?:(documents:readonly NativeDocument[])=>void;
  /** iOS and Android: the picker failed (not a cancel). Without it the error is rethrown. */
  onError?:(error:Error)=>void;
  accessibilityHint?:string;
  testID?:string;
  className?:string;
  labelClassName?:string;
  unstyled?:boolean;
}

export const filePickerRecipe={
  root:"min-h-11 flex-row items-center justify-center gap-2 rounded-control border border-border bg-surface-raised px-4 "+
    "hover:bg-surface-sunken active:opacity-80 focus-visible:ring-2 focus-visible:ring-focus",
  label:"text-sm font-semibold text-text",
} as const;

import { Pressable, Text } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { filePickerRecipe, type FilePickerProps } from "@/components/nyc-tron/ui/components/files/FilePicker.types";

export type { FilePickerProps } from "@/components/nyc-tron/ui/components/files/FilePicker.types";

/**
 * Opens the browser's file chooser from a real button. The `<input type=file>`
 * is created on press and never rendered, so the control is the kit's
 * Pressable (keyboard, focus ring, 44pt target) rather than raw HTML UI.
 */
export function FilePicker({
  label,accept,multiple=false,disabled=false,onFiles,accessibilityHint,testID,
  className,labelClassName,unstyled=false,
}:FilePickerProps) {
  const open=()=>{
    if(disabled||typeof document==="undefined")return;
    const input=document.createElement("input");
    input.type="file";
    if(accept)input.accept=accept;
    input.multiple=multiple;
    // Attached while open: Safari ignores click() on a detached file input.
    input.style.display="none";
    // Safari before 16.4 fires no `cancel`, so the window regaining focus
    // after the chooser closes also removes the input. `change` can land
    // just after that focus, hence the delay.
    const done=()=>{input.remove();window.removeEventListener("focus",onFocus);};
    const onFocus=()=>setTimeout(()=>{if(!input.files?.length)done();},1000);
    input.addEventListener("change",()=>{
      const files=Array.from(input.files??[]);
      done();
      if(files.length)onFiles?.(files);
    },{once:true});
    input.addEventListener("cancel",done,{once:true});
    window.addEventListener("focus",onFocus,{once:true});
    document.body.appendChild(input);
    input.click();
  };
  // No receiver for the files: no button, rather than one that picks into nothing.
  if(!onFiles)return null;
  const styled=!unstyled;
  return (
    <Pressable onPress={open} disabled={disabled} testID={testID}
      accessibilityRole="button" accessibilityLabel={label} accessibilityHint={accessibilityHint}
      accessibilityState={{disabled}}
      {...{className:joinClasses(styled&&filePickerRecipe.root,disabled&&"opacity-50",className)}}>
      <Text {...{className:joinClasses(styled&&filePickerRecipe.label,labelClassName)}}>{label}</Text>
    </Pressable>
  );
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
